package org.apache.commons.jxpath.ri.model.jdom;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import javax.xml.namespace.QName;
import org.apache.commons.jxpath.ri.QName;
import org.apache.commons.jxpath.ri.model.NodeIterator;
import org.apache.commons.jxpath.ri.model.NodePointer;
import org.apache.commons.jxpath.ri.model.jdom.JDOMAttributeIterator;
import org.jdom.Attribute;
import org.jdom.Element;
import org.jdom.Namespace;
import org.jdom2.Attribute;
import org.jdom2.Element;
import org.jdom2.Namespace;
import org.junit.*;
import org.junit.Test;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class JDOMAttributeIterator_JDOMAttributeIterator_TriageGen2Test {

    @Mock
    private NodePointer mockParent;

    @Mock
    private Element mockElement;

    @Mock
    private Attribute mockAttribute;

    public JDOMAttributeIterator_JDOMAttributeIterator_TriageGen2Test() {
        MockitoAnnotations.openMocks(this);
    }

    @Test
    public void testConstructor_ParentNotElement() {
        // Test branch where parent.getNode() is not an instance of Element
        when(mockParent.getNode()).thenReturn(new Object());
        QName name = new QName("attr");

        JDOMAttributeIterator iterator = new JDOMAttributeIterator(mockParent, name);

        assertNotNull(iterator);
    }

    @Test
    public void testConstructor_PrefixXml() {
        // Test prefix "xml" branch
        when(mockParent.getNode()).thenReturn(mockElement);
        QName name = new QName("attr", "xml");

        new JDOMAttributeIterator(mockParent, name);

        // Verify we don't call getNamespace for "xml" prefix as it uses Namespace.XML_NAMESPACE
        verify(mockElement, never()).getNamespace(anyString());
    }

    @Test
    public void testConstructor_PrefixExistsAndNamespaceFound_SingleAttribute() {
        // Test prefix exists, namespace found, specific name (not "*")
        when(mockParent.getNode()).thenReturn(mockElement);
        String prefix = "p";
        String localName = "attr";
        QName name = new QName(localName, prefix);
        Namespace ns = Namespace.getNamespace(prefix, "http://test");

        when(mockElement.getNamespace(prefix)).thenReturn(ns);
        when(mockElement.getAttribute(localName, ns)).thenReturn(mockAttribute);

        JDOMAttributeIterator iterator = new JDOMAttributeIterator(mockParent, name);

        // We check if it works without error. Since attributes field is private, 
        // we assume success if no exception is thrown and logic flows.
        assertNotNull(iterator);
    }

    @Test
    public void testConstructor_PrefixExistsButNamespaceNotFound() {
        // Test branch where prefix is provided but element.getNamespace(prefix) returns null
        when(mockParent.getNode()).thenReturn(mockElement);
        QName name = new QName("attr", "unknown");
        when(mockElement.getNamespace("unknown")).thenReturn(null);

        JDOMAttributeIterator iterator = new JDOMAttributeIterator(mockParent, name);

        assertNotNull(iterator);
    }

    @Test
    public void testConstructor_NoPrefix() {
        // Test branch where prefix is null (Namespace.NO_NAMESPACE)
        when(mockParent.getNode()).thenReturn(mockElement);
        QName name = new QName("attr", null);

        new JDOMAttributeIterator(mockParent, name);

        verify(mockElement, never()).getNamespace(anyString());
    }

    @Test
    public void testConstructor_WildcardName_AllAttributes() {
        // Test lname.equals("*") branch
        when(mockParent.getNode()).thenReturn(mockElement);
        QName name = new QName("*", "p");
        Namespace ns = Namespace.getNamespace("p", "http://test");

        when(mockElement.getNamespace("p")).thenReturn(ns);

        Attribute attr1 = mock(Attribute.class);
        Attribute attr2 = mock(Attribute.class);
        Attribute attr3 = mock(Attribute.class);

        when(attr1.getNamespace()).thenReturn(ns);
        when(attr2.getNamespace()).thenReturn(ns);
        when(attr3.getNamespace()).thenReturn(Namespace.getNamespace("other", "http://other"));

        List<Attribute> allAttrs = java.util.Arrays.asList(attr1, attr2, attr3);
        when(mockElement.getAttributes()).thenReturn(allAttrs);

        JDOMAttributeIterator iterator = new JDOMAttributeIterator(mockParent, name);
        assertNotNull(iterator);
    }

    @Test
    public void testConstructor_SpecificName_AttributeNotFound() {
        // Test branch where lname != "*" but attribute is null
        when(mockParent.getNode()).thenReturn(mockElement);
        QName name = new QName("missing", "p");
        Namespace ns = Namespace.getNamespace("p", "http://test");

        when(mockElement.getNamespace("p")).thenReturn(ns);
        when(mockElement.getAttribute("missing", ns)).thenReturn(null);

        JDOMAttributeIterator iterator = new JDOMAttributeIterator(mockParent, name);
        assertNotNull(iterator);
    }

    @Test
    public void testConstructor_WildcardName_NoAttributesInList() {
        // Test branch where lname == "*" but list is empty
        when(mockParent.getNode()).thenReturn(mockElement);
        QName name = new QName("*", "p");
        Namespace ns = Namespace.getNamespace("p", "http://test");

        when(mockElement.getNamespace("p")).thenReturn(ns);
        when(mockElement.getAttributes()).thenReturn(java.util.Collections.emptyList());

        JDOMAttributeIterator iterator = new JDOMAttributeIterator(mockParent, name);
        assertNotNull(iterator);
    }
}
